#[cfg(test)]mod static2941_queue_development_tests{
 use super::*;
 use super::static_effect_ingress_development_tests::world;
 use crate::modern_lito::{native_static2941::{Queue,Prepared,History,Stage},native_world::World,tower_assets::Static2941Bank,shared_action_catalog::SharedActionCatalog};
 fn add(w:&mut World,q:&mut Queue,n:u64)->(IngressReceipt,u64){let mut b=vec![0x37];b.extend(w.own_actor().unwrap().id.to_le_bytes());b.extend(2941u16.to_le_bytes());let r=IngressReceipt::decoded(9,n);let dispatch=Instant::now();w.accept_received(&b,r).unwrap();let s=w.effects.last().unwrap().sequence;assert!(q.admit_received(w,9,r,dispatch).unwrap());(r,s)}
 fn bank()->(std::path::PathBuf,Arc<Static2941Bank>){let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit original root").into();let c=SharedActionCatalog::load(&root,&AtomicBool::new(false)).unwrap();let bank=Arc::new(Static2941Bank::load(&c,&AtomicBool::new(false)).unwrap());(root,bank)}
 fn ready(w:&mut World,q:&mut Queue,s:u64,root:&std::path::Path,bank:Arc<Static2941Bank>){let p=Prepared::from_bank(bank,w.static_effect_receipts[&s].scheduled_lease().unwrap(),&AtomicBool::new(false)).unwrap().unwrap();assert!(q.enqueue_prepared(w,9,root,p).unwrap());}
 #[test]#[ignore="LITO_SHARED_RESOURCE_ROOT; real2941/1120 bank required before enqueue"]
 fn distinct_decode_dispatch_constructor_enqueue_samples_and_zero_deadline_are_bound(){let(root,b)=bank();let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let l=w.static_effect_receipts[&s].scheduled_lease().unwrap().clone();assert!(l.waiting());assert_eq!(l.deadline(),None);ready(&mut w,&mut q,s,&root,b);assert!(l.decoded_at()<=l.dispatched_at()&&l.dispatched_at()<=l.constructed_at());assert!(l.constructed_at()<=l.resource_ready_at().unwrap()&&l.resource_ready_at()<=l.enqueued_at());assert_eq!(l.deadline(),l.enqueued_at());assert!(l.drawable());}
 #[test]#[ignore="LITO_SHARED_RESOURCE_ROOT; actual bank, snapshot revocation"]
 fn copied_world_observer_is_revoked_by_controller_drain_without_mutating_the_copy(){let(root,b)=bank();let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);ready(&mut w,&mut q,s,&root,b);let old=w.clone();let l=old.static_effect_receipts[&s].scheduled_lease().unwrap().clone();let rev=w.visual_revision;let now=Instant::now();let report=q.drain_due(&mut w,9,now).unwrap();assert_eq!(report.sampled_at,Some(now));assert_eq!(report.retired_sequences,vec![s]);assert_eq!(w.visual_revision,rev+1);assert_eq!(old.visual_revision,rev);assert!(!l.current(&old,9));}
 #[test]#[ignore="LITO_SHARED_RESOURCE_ROOT; actual prepared bank and callback order"]
 fn equal_or_earlier_deadlines_keep_admission_order_in_the_callback_receipt(){let(root,bank)=bank();let mut w=world();let mut q=Queue::default();let(_,a)=add(&mut w,&mut q,1);let(_,b)=add(&mut w,&mut q,2);ready(&mut w,&mut q,a,&root,bank.clone());ready(&mut w,&mut q,b,&root,bank);assert!(w.static_effect_receipts[&a].scheduled_lease().unwrap().deadline()<=w.static_effect_receipts[&b].scheduled_lease().unwrap().deadline());assert_eq!(q.drain_due(&mut w,9,Instant::now()).unwrap().retired_sequences,vec![a,b]);}
 #[test]fn ring_eviction_revokes_only_removed_observers_and_keeps_queue_bounded(){let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let l=w.static_effect_receipts[&s].scheduled_lease().unwrap().clone();for n in 2..=130{add(&mut w,&mut q,n);}assert!(!l.active());assert_eq!(w.static_effect_receipts.len(),128);assert!(q.drain_due(&mut w,9,Instant::now()).unwrap().retired_sequences.is_empty());}
 #[test]fn owner_change_and_queue_drop_revoke_old_snapshots(){let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let l=w.static_effect_receipts[&s].scheduled_lease().unwrap().clone();q.synchronize(&w,10);assert!(!l.active());let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let l=w.static_effect_receipts[&s].scheduled_lease().unwrap().clone();drop(q);assert!(!l.active());}
 #[test]fn retired_or_already_scheduled_receipt_cannot_create_another_lifetime(){let mut w=world();let mut q=Queue::default();let(r,s)=add(&mut w,&mut q,1);assert!(!q.admit_received(&mut w,9,r,Instant::now()).unwrap());q.retire();assert!(!q.admit_received(&mut w,9,r,Instant::now()).unwrap());assert!(!w.static_effect_receipts[&s].scheduled_lease().unwrap().active());}
 #[test]fn wrong_connection_is_rejected_before_revoking_the_current_owner(){let mut w=world();let mut q=Queue::default();let(r,s)=add(&mut w,&mut q,1);assert!(q.admit_received(&mut w,10,r,Instant::now()).is_err());assert!(w.static_effect_receipts[&s].scheduled_lease().unwrap().current(&w,9));}
 #[test]fn untimed_world_accept_does_not_create_a_controller_clock_or_deadline(){let mut w=world();let mut q=Queue::default();let mut b=vec![0x37];b.extend(w.own_actor().unwrap().id.to_le_bytes());b.extend(2941u16.to_le_bytes());w.accept(&b).unwrap();let r=IngressReceipt::decoded(9,1);assert!(!q.admit_received(&mut w,9,r,Instant::now()).unwrap());assert!(q.drain_due(&mut w,9,Instant::now()).unwrap().retired_sequences.is_empty());}
 #[test]fn pending_resource_never_acquires_a_deadline_from_poll_or_paint(){let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let l=w.static_effect_receipts[&s].scheduled_lease().unwrap().clone();for _ in 0..3{assert!(q.drain_due(&mut w,9,Instant::now()).unwrap().retired_sequences.is_empty());}assert!(l.waiting());assert_eq!(l.enqueued_at(),None);assert_eq!(l.resource_ready_at(),None);}
 #[test]fn source_history_cannot_reset_a_retired_token(){let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let old=History::for_world(&w);assert!(old.active_sequences().contains(&s));let other=old.for_source(false);q.retire();let mut merged=other;merged.merge(&old);assert!(merged.active_sequences().is_empty());}
 #[test]#[ignore="LITO_SHARED_RESOURCE_ROOT; reject a genuine proof under a different root"]
 fn wrong_root_resource_proof_does_not_start_the_callback_clock(){let(_,b)=bank();let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let l=w.static_effect_receipts[&s].scheduled_lease().unwrap().clone();let p=Prepared::from_bank(b,&l,&AtomicBool::new(false)).unwrap().unwrap();assert!(!q.enqueue_prepared(&mut w,9,std::path::Path::new("this-root-is-not-the-original-static-bank"),p).unwrap());assert!(l.waiting());assert_eq!(l.deadline(),None);}
 #[test]fn missing_spr_source_keeps_pending_and_does_not_create_a_fake_timer(){static NEXT:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);let base=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("target/current/verification/static2941-empty-source");std::fs::create_dir_all(&base).unwrap();let root=base.join(format!("{}-{}",std::process::id(),NEXT.fetch_add(1,Ordering::Relaxed)));std::fs::create_dir(&root).unwrap();let mut w=world();let mut q=Queue::default();let(_,s)=add(&mut w,&mut q,1);let mut stage=Stage::default();assert!(stage.prepare(&root,&w,&AtomicBool::new(false),&mut None).unwrap().is_empty());assert!(stage.receipt()["error"].is_string());assert!(w.static_effect_receipts[&s].scheduled_lease().unwrap().waiting());assert!(q.drain_due(&mut w,9,Instant::now()).unwrap().retired_sequences.is_empty());std::fs::remove_dir(&root).unwrap();}
}
